/**
 * rule-registry.ts — 统一规则注册中心 (Phase 2.1)
 *
 * 合并 BUILTIN_RULES + knowledge-curator rules + global-evolution suggestions。
 * 规则增删改查 + 触发匹配 + 进化元数据 + 版本历史。
 */
import { createLogger } from '../../infra/logger';

const log = createLogger('diagnosis/rule-registry');

// ═══ Types ═══

export interface RuleEvolutionMeta {
  calibratedAt?: string;
  calibrationOrgCount?: number;
  previousVersions: string[];
}

export interface DiagnosticRule {
  id: string;
  name: string;
  source: 'expert_template' | 'engine_calibrated' | 'engine_discovered';
  status: 'active' | 'canary' | 'deprecated' | 'disabled';
  confidence: number;
  version: number;
  triggerOn: string;
  edgeType?: string;
  minSeverity: 'critical' | 'high' | 'medium' | 'low';
  action: { title: string; description: string; priority: string; assigneeRole: string; estimatedHours: number };
  cooldownMs: number;
  evolutionMeta?: RuleEvolutionMeta;
}

export interface RuleFilter {
  source?: DiagnosticRule['source'];
  status?: DiagnosticRule['status'];
}

const SEVERITY_ORDER: Record<string, number> = { critical: 4, high: 3, medium: 2, low: 1 };

// ═══ Snapshot helper ═══

export function snapshotRule(rule: DiagnosticRule): string {
  const snapshot = { ...rule };
  if (snapshot.evolutionMeta) {
    const { previousVersions, ...rest } = snapshot.evolutionMeta;
    snapshot.evolutionMeta = rest as RuleEvolutionMeta;
  }
  return JSON.stringify(snapshot);
}

// ═══ RuleRegistry ═══

export class RuleRegistry {
  private db: any;
  private cache = new Map<string, DiagnosticRule>();

  constructor(db: any) {
    this.db = db;
    this.initSchema();
    this.loadFromDb();
  }

  // ═══ Schema ═══

  private initSchema(): void {
    this.db.exec(`
      CREATE TABLE IF NOT EXISTS diagnostic_rules (
        id TEXT PRIMARY KEY,
        name TEXT NOT NULL,
        source TEXT NOT NULL CHECK(source IN ('expert_template','engine_calibrated','engine_discovered')),
        status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','canary','deprecated','disabled')),
        confidence REAL NOT NULL DEFAULT 0.5,
        version INTEGER NOT NULL DEFAULT 1,
        trigger_on TEXT NOT NULL,
        edge_type TEXT,
        min_severity TEXT NOT NULL DEFAULT 'medium',
        action_json TEXT NOT NULL DEFAULT '{}',
        cooldown_ms INTEGER NOT NULL DEFAULT 86400000,
        calibrated_at TEXT,
        calibration_org_count INTEGER,
        created_at TEXT DEFAULT (datetime('now')),
        updated_at TEXT DEFAULT (datetime('now'))
      );
      CREATE INDEX IF NOT EXISTS idx_dr_source ON diagnostic_rules(source);
      CREATE INDEX IF NOT EXISTS idx_dr_status ON diagnostic_rules(status);

      CREATE TABLE IF NOT EXISTS rule_versions (
        rule_id TEXT NOT NULL,
        version INTEGER NOT NULL,
        rule_json TEXT NOT NULL,
        changed_at TEXT DEFAULT (datetime('now')),
        PRIMARY KEY (rule_id, version)
      );
    `);
  }

  private loadFromDb(): void {
    const rows = this.db.prepare('SELECT * FROM diagnostic_rules').all() as any[];
    for (const r of rows) {
      this.cache.set(r.id, rowToRule(r));
    }
  }

  // ═══ CRUD ═══

  register(rule: DiagnosticRule): void {
    this.db.prepare(`
      INSERT OR REPLACE INTO diagnostic_rules
        (id, name, source, status, confidence, version, trigger_on, edge_type,
         min_severity, action_json, cooldown_ms, calibrated_at, calibration_org_count)
      VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)
    `).run(
      rule.id, rule.name, rule.source, rule.status, rule.confidence, rule.version,
      rule.triggerOn, rule.edgeType || null, rule.minSeverity,
      JSON.stringify(rule.action), rule.cooldownMs,
      rule.evolutionMeta?.calibratedAt || null,
      rule.evolutionMeta?.calibrationOrgCount || null,
    );
    this.cache.set(rule.id, { ...rule });
    log.info({ id: rule.id, source: rule.source }, '规则已注册');
  }

  listRules(filter?: RuleFilter): DiagnosticRule[] {
    let rules = [...this.cache.values()];
    if (filter?.source) rules = rules.filter(r => r.source === filter.source);
    if (filter?.status) rules = rules.filter(r => r.status === filter.status);
    return rules;
  }

  getRule(id: string): DiagnosticRule | undefined {
    return this.cache.get(id);
  }

  enableRule(id: string): void {
    this.updateStatus(id, 'active');
  }

  disableRule(id: string): void {
    this.updateStatus(id, 'disabled');
  }

  private updateStatus(id: string, status: DiagnosticRule['status']): void {
    const rule = this.cache.get(id);
    if (!rule) return;
    rule.status = status;
    this.db.prepare('UPDATE diagnostic_rules SET status=? WHERE id=?').run(status, id);
  }

  updateConfidence(id: string, confidence: number): void {
    const rule = this.cache.get(id);
    if (!rule) return;
    rule.confidence = Math.max(0, Math.min(1, confidence));
    this.db.prepare('UPDATE diagnostic_rules SET confidence=? WHERE id=?').run(rule.confidence, id);
  }

  /** 版本递增 + 历史快照 + previousVersions 限制 */
  incrementVersion(id: string): void {
    const rule = this.cache.get(id);
    if (!rule) return;

    // 快照当前版本
    this.db.prepare('INSERT OR REPLACE INTO rule_versions (rule_id, version, rule_json) VALUES (?,?,?)')
      .run(id, rule.version, snapshotRule(rule));

    // 递增
    rule.version++;
    if (!rule.evolutionMeta) rule.evolutionMeta = { previousVersions: [] };
    rule.evolutionMeta.previousVersions.push(`v${rule.version - 1}`);
    if (rule.evolutionMeta.previousVersions.length > 3) {
      rule.evolutionMeta.previousVersions = rule.evolutionMeta.previousVersions.slice(-3);
    }

    this.db.prepare('UPDATE diagnostic_rules SET version=? WHERE id=?').run(rule.version, id);
  }

  getVersionHistory(ruleId: string): Array<{ version: number; ruleJson: string; changedAt: string }> {
    return this.db.prepare(
      'SELECT * FROM rule_versions WHERE rule_id=? ORDER BY version DESC'
    ).all(ruleId) as any[];
  }

  // ═══ Trigger Matching ═══

  getTriggeredRules(alert: { type: string; severity: string; edgeType?: string }): DiagnosticRule[] {
    const alertSeverity = SEVERITY_ORDER[alert.severity] ?? 0;
    return [...this.cache.values()]
      .filter(r => r.status === 'active' || r.status === 'canary')
      .filter(r => {
        // triggerOn 匹配
        if (r.triggerOn !== '*' && r.triggerOn !== alert.type) return false;
        // edgeType 匹配
        if (r.edgeType && r.edgeType !== '*' && r.edgeType !== alert.edgeType) return false;
        // severity 门禁
        const ruleSev = SEVERITY_ORDER[r.minSeverity] ?? 0;
        if (alertSeverity < ruleSev) return false;
        return true;
      })
      .sort((a, b) => (SEVERITY_ORDER[b.minSeverity] ?? 0) - (SEVERITY_ORDER[a.minSeverity] ?? 0));
  }
}

// ═══ Row → Rule ═══

function rowToRule(r: any): DiagnosticRule {
  return {
    id: r.id, name: r.name,
    source: r.source, status: r.status,
    confidence: r.confidence, version: r.version,
    triggerOn: r.trigger_on, edgeType: r.edge_type || undefined,
    minSeverity: r.min_severity,
    action: JSON.parse(r.action_json || '{}'),
    cooldownMs: r.cooldown_ms,
    evolutionMeta: {
      calibratedAt: r.calibrated_at || undefined,
      calibrationOrgCount: r.calibration_org_count || undefined,
      previousVersions: [], // loaded lazily from rule_versions
    },
  };
}
